export function getAllLocationLandingPages(): LocationLandingPage[] {
  return ALL_LOCATIONS;
}

export function getAllLocationSlugs(): string[] {
  return ALL_LOCATIONS.map((loc) => loc.slug);
}

export function getLocationBySlug(slug: string): LocationLandingPage | undefined {
  if (!slug || typeof slug !== 'string') return undefined;
  const cleanSlug = slug.replace(/^stock-market-classes-in-/, '').toLowerCase();
  return ALL_LOCATIONS.find((loc) => loc.slug === cleanSlug);
}

export function getLocationPath(slug: string): string {
  if (!slug || typeof slug !== 'string') return '/service-areas';
  const cleanSlug = slug.replace(/^stock-market-classes-in-/, '').toLowerCase();
  return `/stock-market-classes-in-${cleanSlug}`;
}

export function getLocationsByState(): Record<string, LocationLandingPage[]> {
  const map: Record<string, LocationLandingPage[]> = {};
  for (const loc of ALL_LOCATIONS) {
    if (!map[loc.state]) {
      map[loc.state] = [];
    }
    map[loc.state].push(loc);
  }
  return map;
}

export function getNearbyLocations(currentSlug: string, count = 6): LocationLandingPage[] {
  const current = getLocationBySlug(currentSlug);
  if (!current) return ALL_LOCATIONS.slice(0, count);

  // First try same region
  const sameRegion = ALL_LOCATIONS.filter(
    (loc) => loc.slug !== current.slug && loc.region === current.region
  );
  if (sameRegion.length >= count) {
    return sameRegion.slice(0, count);
  }

  // Then try same state
  const sameState = ALL_LOCATIONS.filter(
    (loc) => loc.slug !== current.slug && loc.state === current.state && !sameRegion.includes(loc)
  );
  const combined = [...sameRegion, ...sameState];
  if (combined.length >= count) {
    return combined.slice(0, count);
  }

  // Fallback to general list
  const others = ALL_LOCATIONS.filter(
    (loc) => loc.slug !== current.slug && !combined.includes(loc)
  );
  return [...combined, ...others].slice(0, count);
}
